package com.wms.controller;
import com.wms.common.Result; import com.wms.dto.*; import com.wms.service.RoleService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/roles")
public class RoleController {private final RoleService s;public RoleController(RoleService s){this.s=s;} @GetMapping @PreAuthorize("hasAnyAuthority('system:role','system:user')") public Result<List<RoleDTO>> list(){return Result.ok(s.list());} @GetMapping("/permissions") @PreAuthorize("hasAuthority('system:role')") public Result<List<PermissionGroupDTO>> permissions(){return Result.ok(s.permissions());} @PostMapping @PreAuthorize("hasAuthority('system:role')") public Result<RoleDTO> create(@Valid @RequestBody RoleSaveReq r){return Result.ok(s.create(r));} @PutMapping("/{id}") @PreAuthorize("hasAuthority('system:role')") public Result<RoleDTO> update(@PathVariable Long id,@Valid @RequestBody RoleSaveReq r){return Result.ok(s.update(id,r));} @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('system:role')") public Result<Void> delete(@PathVariable Long id){s.delete(id);return Result.ok();}}
